#include <string>
#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    int maximumScore(string s, vector<int>& values) {
        int c = 0;
        for (char ch : s) if (ch == '1') c++;
        if (c == 0) return 0;
        sort(values.rbegin(), values.rend());
        int ans = 0;
        for (int i = 0; i < c; i++) ans += values[i];
        return ans;
    }
};

import java.util.*;

class Solution {
    public int maximumScore(String s, int[] values) {
        int c = 0;
        for (char ch : s.toCharArray()) if (ch == '1') c++;
        if (c == 0) return 0;
        Arrays.sort(values);
        int ans = 0;
        int n = values.length;
        for (int i = 0; i < c; i++) ans += values[n - 1 - i];
        return ans;
    }
}

var maximumScore = function(s, values) {
    const c = [...s].filter(ch => ch === '1').length;
    if (c === 0) return 0;
    values.sort((a, b) => b - a);
    return values.slice(0, c).reduce((sum, v) => sum + v, 0);
};
